function setupFixtures(): FixtureSet {
	const root = mkdtempSync(join(tmpdir(), 'analyze-fixtures-'));
	return setupFixturesAt(root);
}

function setupFixturesAt(root: string): FixtureSet {
	mkdirSync(root, { recursive: true });

	const tiny      = buildTinyMultiLangRepo(join(root, 'tiny-multi-lang-repo'));
	const sqlite    = buildSeededSqlite(join(root, 'seeded.sqlite'));
	const csvDir    = buildSeededCsvDir(join(root, 'seeded-csv-dir'));
	const manifests = buildSeededManifests(join(root, 'seeded-manifests'));
	const empty     = buildEmptyRepo(join(root, 'empty-repo'));
	const unindexed = buildUnindexedRepo(join(root, 'unindexed-repo'));

	return {
		root,
		tinyMultiLangRepo: tiny,
		seededSqlite:      sqlite,
		seededCsvDir:      csvDir,
		seededManifests:   manifests,
		emptyRepo:         empty,
		unindexedRepo:     unindexed,
	};
}

function teardownFixtures(fixtures: FixtureSet): void {
	rmSync(fixtures.root, { recursive: true, force: true });
}

class AnalyzePromptValidationError extends Error {
	readonly missing: readonly AnalyzePromptFailure[];

	constructor(missing: AnalyzePromptFailure[]) {
		const list = missing
			.map(m => `  - ${m.componentId}: ${m.path} (${m.reason})`)
			.join('\n');
		super(
			`analyze: prompt validation failed:\n${list}\n` +
				'Fix: ensure every prompts/analyze/<component>.system.md exists and is non-empty.',
		);
		this.name = 'AnalyzePromptValidationError';
		this.missing = missing;
	}
}

function validateAnalyzePrompts(): void {
	const failures: AnalyzePromptFailure[] = [];
	const components = collectComponentPrompts();

	for (const { componentId, relPath } of components) {
		const abs = isAbsolute(relPath) ? relPath : resolveRelativeToInsrcRoot(relPath);

		try {
			statSync(abs);
		} catch (err) {
			failures.push({
				componentId,
				path:   abs,
				reason: (err as NodeJS.ErrnoException).code === 'ENOENT'
					? 'file not found'
					: `stat failed: ${(err as Error).message}`,
			});
			continue;
		}

		let body: string;
		try {
			body = readFileSync(abs, 'utf8');
		} catch (err) {
			failures.push({
				componentId,
				path:   abs,
				reason: `read failed: ${(err as Error).message}`,
			});
			continue;
		}

		if (body.trim().length === 0) {
			failures.push({ componentId, path: abs, reason: 'file is empty' });
			continue;
		}

		log.debug({ componentId, path: abs, bytes: body.length }, 'analyze prompt loaded');
	}

	if (failures.length > 0) {
		throw new AnalyzePromptValidationError(failures);
	}

	log.info({ count: components.length }, 'analyze prompts validated');
}

function omitEmpty(label: string, body: string): string {
	if (body.trim().length === 0) {
		return '';
	}
	return `## ${label}\n\n${body.trim()}\n`;
}

function assembleMarkdown(bundle: AnalyzeContextBundle): string {
	const emptyLayers = new Set<BundleLayerName>(bundle.meta?.emptyLayers ?? []);
	const sections: string[] = [];

	// This text goes into a model's prompt (the classifier's, the planner's).
	// A bundle with a report leads with its completeness line, so the model is
	// told what the findings below leave out. A bundle with none gets nothing:
	// no "not recorded" sentence enters a prompt.
	const head = completenessHeadLine(bundle.report, 'nothing');
	if (head !== undefined) sections.push(head);

	for (const layer of RENDER_ORDER) {
		const body = bundle[layer];

		if (emptyLayers.has(layer) || body.trim().length === 0) {
			continue;
		}

		if (layer === 'system') {
			sections.push(body.trim());
			continue;
		}

		sections.push(omitEmpty(LAYER_LABELS[layer], body));
	}

	sections.push(CONTRACT_FOOTER_MD);

	return sections.join('\n\n');
}

function cacheFilePathFor(runId: string, key: CacheKey): string {
	const dir = PATHS.analyzeContext(runId);
	switch (key.mode) {
		case 'classification': return join(dir, 'classification.json');
		case 'run':            return join(dir, 'run-bundle.json');
		case 'task': {
			if (key.taskId === undefined || key.taskId.length === 0) {
				throw new TypeError("cacheFilePathFor: taskId is required when mode='task'");
			}
			return join(dir, `${key.taskId}.bundle.json`);
		}
	}
}

function readBundle(
	runId: string,
	key:   CacheKey,
	opts:  ShapeOpts,
	currentLastIndexedAt?: number,
): AnalyzeContextBundle | null {
	if (opts.bypassCache === true) {
		return null;
	}

	const path = cacheFilePathFor(runId, key);

	let raw: string;
	try {
		raw = readFileSync(path, 'utf8');
	} catch (err) {
		if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
			return null;
		}
		log.warn({ path, err: (err as Error).message }, 'cache read failed; treating as miss');
		return null;
	}

	let parsed: CacheFileBody;
	try {
		parsed = JSON.parse(raw) as CacheFileBody;
	} catch (err) {
		log.warn({ path, err: (err as Error).message }, 'cache file is not valid JSON; discarding');
		safeUnlink(path);
		return null;
	}

	if (typeof parsed?.key !== 'string' || parsed.bundle === undefined) {
		log.warn({ path }, 'cache file has unexpected shape; discarding');
		safeUnlink(path);
		return null;
	}

	if (parsed.key !== key.hash) {
		// Mismatched key -- the slot belongs to a stale invocation. Discard
		// so the next miss-write can land cleanly.
		log.debug({ path, expected: key.hash, found: parsed.key }, 'cache key mismatch; discarding');
		safeUnlink(path);
		return null;
	}

	// Indexer-timestamp freshness check. If the registry reports a
	// newer lastIndexedAt than the bundle's recorded value, the bundle
	// reflects an older view of the indexed graph and must be rebuilt.
	if (currentLastIndexedAt !== undefined && isStaleByIndexer(parsed.bundle, currentLastIndexedAt)) {
		log.debug(
			{
				path,
				cached:   parsed.bundle.meta?.repoLastIndexedAt,
				registry: currentLastIndexedAt,
			},
			'cached bundle stale (registry lastIndexedAt advanced); discarding',
		);
		safeUnlink(path);
		return null;
	}

	return parsed.bundle;
}

function isStaleByIndexer(
	bundle: AnalyzeContextBundle,
	currentLastIndexedAt: number,
): boolean {
	const cached = bundle.meta?.repoLastIndexedAt;
	if (cached === undefined) {
		return true;
	}
	return currentLastIndexedAt > cached;
}

function writeBundle(
	runId:  string,
	key:    CacheKey,
	bundle: AnalyzeContextBundle,
): void {
	const path = cacheFilePathFor(runId, key);
	mkdirSync(dirname(path), { recursive: true });

	const body: CacheFileBody = { key: key.hash, bundle };
	const json = JSON.stringify(body, null, '\t');

	const tmpPath = `${path}.tmp-${process.pid}-${Date.now()}`;
	writeFileSync(tmpPath, json, 'utf8');
	// fs.renameSync is atomic across same-filesystem paths on POSIX; we
	// rely on the cache dir + tmp file living in the same FS (both under
	// ~/.insrc/analyze/<runId>/context).
	renameSync(tmpPath, path);
}

function invalidateBundle(runId: string, key: CacheKey): void {
	safeUnlink(cacheFilePathFor(runId, key));
}

class DecomposerLlmUnavailableError extends Error {
	/** The underlying failure's own message, without this error's prefix. */
	readonly detail: string;

	constructor(cause: string) {
		// Provider-neutral: the planning provider is role-routed and
		// need not be Ollama.
		super(`The model call for planning failed: ${cause}`);
		this.name = 'DecomposerLlmUnavailableError';
		this.detail = cause;
	}
}

class DecomposerSchemaUnrecoverable extends Error {
	constructor(errors: readonly string[]) {
		super(`Decomposer structured output unrecoverable: ${errors.join('; ')}`);
		this.name = 'DecomposerSchemaUnrecoverable';
	}
}

class DecomposerPromptMissingError extends Error {
	readonly path: string;

	constructor(path: string) {
		super(`Decomposer prompt file missing: ${path}`);
		this.name = 'DecomposerPromptMissingError';
		this.path = path;
	}
}

async function decompose(args: DecomposeArgs): Promise<ExplorationPlan> {
	const cfg = loadAnalyzeConfig();
	const promptContent = loadPromptFile();
	const provider = args.provider ?? resolveRoleProvider('analyze.decompose', cfg);

	const messages = buildMessages(promptContent, args.intent, args.scope);

	let raw: {
		answerType:    AnswerType;
		explorations:  Exploration[];
		synthesisHint: string;
	};
	try {
		raw = await provider.completeStructured(
			messages,
			DECOMPOSE_SCHEMA,
			{
				maxAttempts:     cfg.shaper.structuredOutputRetries,
				disableThinking: true,
				// Tiny output: 1 top-level object + <=8 exploration
				// entries. 2048 tokens is generous.
				maxTokens:       2_048,
			},
		);
	} catch (err) {
		const errClass = classifyError(err);
		if (errClass instanceof DecomposerLlmUnavailableError) throw errClass;
		throw errClass;
	}

	// Validate id ordering + dependsOn topology (schema-level checks
	// aren't strong enough to enforce this).
	validatePlanTopology(raw.explorations);

	log.info(
		{
			runId:            args.runId,
			answerType:       raw.answerType,
			explorationCount: raw.explorations.length,
			target:           args.intent.target,
			scope:            args.intent.scope,
			focus:            args.intent.focus,
		},
		'decomposer: plan emitted',
	);

	return {
		answerType:    raw.answerType,
		explorations:  raw.explorations,
		synthesisHint: raw.synthesisHint,
	};
}

function prepareDecompose(intent: ClassifiedIntent, scope: ResolvedScope): DecomposePrepared {
	const promptContent = loadPromptFile();
	const messages = buildMessages(promptContent, intent, scope);
	return {
		systemPrompt: messages[0]!.content as string,
		userTurn:     messages[1]!.content as string,
		schema:       DECOMPOSE_SCHEMA,
	};
}

function finalizeDecompose(raw: unknown): ExplorationPlan {
	const result = validateAgainstSchema<{
		answerType:    AnswerType;
		explorations:  Exploration[];
		synthesisHint: string;
	}>(DECOMPOSE_SCHEMA, raw);
	if (!result.ok) {
		throw new DecomposerSchemaUnrecoverable(result.errors);
	}
	validatePlanTopology(result.value.explorations);
	return {
		answerType:    result.value.answerType,
		explorations:  result.value.explorations,
		synthesisHint: result.value.synthesisHint,
	};
}

class ShaperLlmUnavailableError extends Error {
	/**
	 * `call` names the pipeline call that failed. With it the message
	 * is provider-neutral (the planning + answer-writing providers are
	 * role-routed and need not be Ollama); without it the message is
	 * the tool loop's, where the provider is the local one.
	 */
	constructor(cause: string, call?: ShaperModelCall) {
		super(
			call !== undefined
				? `The model call for ${call} failed: ${cause}`
				: `Local Ollama unavailable for shaper invocation: ${cause}`,
		);
		this.name = 'ShaperLlmUnavailableError';
	}
}

function toolOutputText(output: unknown): string {
	if (typeof output === 'string') return output;
	try {
		return JSON.stringify(output) ?? `(the tool returned ${String(output)})`;
	} catch (err) {
		return `(the tool's output has no JSON form: ${err instanceof Error ? err.message : String(err)})`;
	}
}

class ShaperToolLoopExhausted extends Error {
	/** Every tool call the loop made before it reached the limit, with what the tool returned. */
	readonly toolResults: readonly PartialFinding[];
	/**
	 * The file the results were written to. The results are not capped and can
	 * be large, so a failure reported to a caller names this file in its
	 * message and does not carry them. Absent when nothing was gathered or the
	 * file could not be written; the results are then carried in the failure.
	 */
	readonly saved: SavedToolResults | undefined;

	constructor(turns: number, toolResults: readonly PartialFinding[] = [], saved?: SavedToolResults) {
		super(
			`Shaper tool-loop exceeded maxToolTurns=${turns}`
			+ (saved !== undefined
				? `. The ${saved.count} tool result(s) gathered before the limit (${saved.chars} characters, nothing cut) are in ${saved.path}`
				: ''),
		);
		this.name = 'ShaperToolLoopExhausted';
		this.toolResults = toolResults;
		this.saved = saved;
	}
}

function toolLoopExhausted(turns: number, toolResults: readonly PartialFinding[]): ShaperToolLoopExhausted {
	return new ShaperToolLoopExhausted(turns, toolResults, saveToolResults(toolResults));
}

function saveToolResults(
	toolResults: readonly PartialFinding[],
	dir: string = join(tmpdir(), 'insrc-analyze'),
): SavedToolResults | undefined {
	if (toolResults.length === 0) return undefined;
	try {
		mkdirSync(dir, { recursive: true });
		const path = join(dir, `tool-results-${randomUUID()}.json`);
		writeFileSync(path, JSON.stringify(toolResults, null, 2), 'utf8');
		return { path, count: toolResults.length, chars: toolResults.reduce((n, r) => n + r.content.length, 0) };
	} catch (err) {
		log.warn({ dir, err: err instanceof Error ? err.message : String(err) }, 'tool-loop results could not be written to a file; they stay in the failure');
		return undefined;
	}
}

function toolLoopExhaustedData(err: ShaperToolLoopExhausted): Readonly<Record<string, unknown>> {
	return err.saved !== undefined
		? { toolResultsFile: err.saved.path, toolResultCount: err.saved.count, toolResultChars: err.saved.chars }
		: { toolResults: err.toolResults };
}

class ShaperSchemaUnrecoverable extends Error {
	constructor(retries: number, lastErrors: readonly string[]) {
		super(
			`Shaper completeStructured exhausted ${retries} retries: ` +
				lastErrors.join('; '),
		);
		this.name = 'ShaperSchemaUnrecoverable';
	}
}

class ShaperPromptMissingError extends Error {
	/**
	 * Set when the missing prompt is the answer-writing one: that prompt is
	 * loaded after the lookups ran, so what they found is carried with the
	 * failure. A missing planning prompt is found before any lookup and has none.
	 */
	readonly found: AnswerStepFound | undefined;

	constructor(promptPath: string, found?: AnswerStepFound) {
		super(`Shaper prompt file missing: ${promptPath}`);
		this.name = 'ShaperPromptMissingError';
		this.found = found;
	}
}

class ShaperInvalidInputError extends Error {
	constructor(detail: string) {
		super(`Shaper inputs are invalid: ${detail}`);
		this.name = 'ShaperInvalidInputError';
	}
}

class ShaperNoPlanError extends Error {
	constructor(detail: string) {
		super(`No plan could be made for this request: ${detail}`);
		this.name = 'ShaperNoPlanError';
	}
}

class ShaperAnswerStepFailedError extends Error {
	readonly reason: AnswerStepFailureReason;
	readonly found:  AnswerStepFound;

	constructor(reason: AnswerStepFailureReason, detail: string, found: AnswerStepFound) {
		const failure = `${ANSWER_STEP_FAILURE_TEXT[reason]}: ${detail}`;
		super(`The answer could not be written after ${found.results.length} lookup(s) ran -- ${failure}`);
		this.name = 'ShaperAnswerStepFailedError';
		this.reason = reason;
		this.found = { results: found.results, report: { ...found.report, answerFailure: failure } };
	}
}

async function runShaper(args: RunShaperArgs): Promise<AnalyzeContextBundle> {
	const cfg = loadAnalyzeConfig();
	const { promptPath, invocationMode, shaperId, inputs, opts } = args;
	const runId = opts.runId;

	// (1) Load prompt content; we need its hash for the cache key.
	const promptContent = loadPromptFile(promptPath);

	// (2) Compute cache key.
	const cacheKey: CacheKey = {
		mode:   invocationMode,
		hash:   computeCacheKey(promptContent, inputs),
		...(invocationMode === 'task'
			? { taskId: (inputs as TaskShapeInput).task.taskId }
			: {}),
	};

	// (2.5) Resolve the scope ONCE, for every mode. Everything below
	// that needs the scope's repo, its lookup directory, its entity or
	// its connection takes it from here. For run mode the pairing of
	// the scope's kind with the kind of source is checked first: a
	// request can arrive with a ready-made intent that no classifier
	// validated.
	const scope = await prepareScope(invocationMode, inputs, args.scopeDeps);

	// (3) Resolve the scope's repo lastIndexedAt from the registry. Used
	// for both the cache freshness check below + stamping into meta on
	// write. `undefined` here means the scope target isn't a registered
	// repo (e.g. a 'connection' scope ref) -- the cache layer treats
	// that as "no freshness watermark to check" and skips the check.
	const currentLastIndexedAt = await resolveRepoLastIndexedAt(freshnessPathOf(scope));

	// (4) Cache lookup.
	const cached = readBundle(runId, cacheKey, opts, currentLastIndexedAt);
	if (cached !== null) {
		log.debug(
			{ runId, mode: invocationMode, shaperId, file: cacheFilePathFor(runId, cacheKey) },
			'shaper cache hit',
		);
		return cached;
	}

	// (4.5) Pre-LLM invariant: code-shaper at run-mode against an
	// unindexed scope is a useless invocation (graph queries return
	// empty, dep-closure analysis is impossible) -- abort before
	// paying the Ollama cost. Only the code shaper depends on the
	// indexed graph; data + infra + classification + generic produce
	// reasonable bundles via the filesystem + DB-driver fallbacks
	// even without graph state, so we skip the invariant for them.
	// classification + task modes skip this check too -- by the time
	// a task fires, the run-mode invocation has already validated
	// the closure.
	if (invocationMode === 'run' && shaperId === 'code') {
		await ensureNonEmptyClosure(scope);
	}

	// (4.6) The lookup pipeline: plan lookups -> execute them -> write
	// the answer. Every run-mode request goes through it. It returns a
	// bundle, or the one cause for which it did not proceed, or
	// 'not-applicable' for a mode it does not serve.
	const outcome = await tryExplorationPipeline(
		{ invocationMode, shaperId, inputs, runId, scope },
		args.pipelineSteps ?? REAL_PIPELINE_STEPS,
	);
	// A cause the pipeline names becomes its own typed error here, in
	// one place; an invalid bundle is one more cause. Only a mode the
	// pipeline does not serve (classification, task) continues to the
	// tool loop below. A run-mode request never does: its fallback is
	// the pipeline's own freeform.probe, which drives the same loop.
	const pipelineBundle = settlePipelineOutcome(outcome, (raw, explorationCount, report) => ({
		...raw,
		// Derived from the lookups' own records. Never taken from the model's answer.
		report,
		meta: {
			mode:          invocationMode,
			shaper:        shaperId,
			toolCalls:     explorationCount,
			modelId:       cfg.shaperModel,
			emptyLayers:   deriveEmptyLayers(raw),
			schemaVersion: SCHEMA_VERSION,
			...(currentLastIndexedAt !== undefined ? { repoLastIndexedAt: currentLastIndexedAt } : {}),
		},
	}));
	if (pipelineBundle !== null) {
		writeBundle(runId, cacheKey, pipelineBundle.bundle);
		log.info(
			{
				runId,
				mode:              invocationMode,
				shaperId,
				pipeline:          'exploration',
				explorationCount:  pipelineBundle.explorationCount,
			},
			'shaper invocation complete (exploration pipeline)',
		);
		return pipelineBundle.bundle;
	}

	// (4) Build the LLM message list. Classification + task modes
	// still run the legacy tool loop here -- those flows are out of
	// scope for Phase 6.
	const messages = buildMessages(promptContent, inputs, invocationMode, shaperId);

	// (5) Resolve provider + tool deps.
	const provider = args.provider ?? buildProvider(localToolLoopModel(cfg), cfg.shaper.ollamaNumCtx);
	const toolDeps = buildToolDeps({
		runId,
		shaperId,
		invocationMode,
		scope,
		provider,
	});

	// (6) Run the tool-loop + final structured emit.
	const onTrace = opts.onTrace;
	const { messages: finalMessages, toolCallCount } = await runToolLoop(
		provider,
		messages,
		toolDeps,
		cfg.shaper.maxToolTurns,
		onTrace,
	);

	const rawBundle = await runFinalStructuredEmit(
		provider,
		finalMessages,
		cfg.shaper.structuredOutputRetries,
		cfg.shaper.ollamaNumPredict,
		onTrace,
	);

	// (7) Stamp meta + validate. `repoLastIndexedAt` carries the registry
	// watermark we read pre-Ollama-call. The next invocation's cache
	// read compares against the current watermark to detect a fresh
	// index cycle.
	const bundle: AnalyzeContextBundle = {
		...rawBundle,
		meta: {
			mode:          invocationMode,
			shaper:        shaperId,
			toolCalls:     toolCallCount,
			modelId:       cfg.shaperModel,
			emptyLayers:   deriveEmptyLayers(rawBundle),
			schemaVersion: SCHEMA_VERSION,
			...(currentLastIndexedAt !== undefined ? { repoLastIndexedAt: currentLastIndexedAt } : {}),
		},
	};

	const v = validateBundleWithErrors(bundle);
	if (!v.ok) {
		// completeStructured should have caught this. If we land here the
		// schema or the meta stamp is wrong; surface loudly rather than
		// caching a malformed entry.
		throw new ShaperSchemaUnrecoverable(cfg.shaper.structuredOutputRetries, v.errors);
	}

	// (8) Persist + return.
	writeBundle(runId, cacheKey, bundle);
	log.info(
		{ runId, mode: invocationMode, shaperId, toolCalls: toolCallCount },
		'shaper invocation complete',
	);
	return bundle;
}

async function runShaperToolLoop(
	args: RunShaperToolLoopArgs,
): Promise<ShaperToolLoopResult> {
	const cfg = loadAnalyzeConfig();
	const promptContent = loadPromptFile(args.promptPath);
	const messages = buildMessages(promptContent, args.inputs, args.invocationMode, args.shaperId);
	const provider = args.provider ?? buildProvider(localToolLoopModel(cfg), cfg.shaper.ollamaNumCtx);
	const toolDeps = buildToolDeps({
		runId:          args.runId,
		shaperId:       args.shaperId,
		invocationMode: args.invocationMode,
		scope:          args.scope,
		provider,
	});
	const { messages: finalMessages, toolCallCount } = await runToolLoop(
		provider,
		messages,
		toolDeps,
		cfg.shaper.maxToolTurns,
		args.onTrace,
	);
	const rawBundle = await runFinalStructuredEmit(
		provider,
		finalMessages,
		cfg.shaper.structuredOutputRetries,
		cfg.shaper.ollamaNumPredict,
		args.onTrace,
	);
	return { rawBundle, toolCallCount };
}

async function prepareScope(
	invocationMode: ShaperMode,
	inputs:         RunShaperArgs['inputs'],
	deps?:          ScopeDeps,
): Promise<ResolvedScope> {
	const ref = scopeRefOf(inputs);
	if (invocationMode === 'run' && 'intent' in inputs) {
		const target = (inputs as RunShapeInput).intent.target;
		return resolveScopeForTarget(ref, target, deps);
	}
	return deps !== undefined ? resolveScope(ref, deps) : resolveScope(ref);
}

async function resolveRepoLastIndexedAt(scopePath: string): Promise<number | undefined> {
	if (scopePath.length === 0) return undefined;

	let repos: readonly RegisteredRepo[];
	try {
		repos = await listRepos(null);
	} catch (err) {
		log.debug(
			{ scopePath, err: (err as Error).message },
			'resolveRepoLastIndexedAt: registry read failed; skipping freshness check',
		);
		return undefined;
	}

	let best: RegisteredRepo | undefined;
	for (const r of repos) {
		const isPrefix = scopePath === r.path || scopePath.startsWith(`${r.path}/`);
		if (!isPrefix) continue;
		if (best === undefined || r.path.length > best.path.length) {
			best = r;
		}
	}

	if (best === undefined || best.lastIndexed === undefined) {
		return undefined;
	}

	const ms = Date.parse(best.lastIndexed);
	return Number.isNaN(ms) ? undefined : ms;
}

function errorForPipelineCause(
	cause:   PipelineCause,
	message: string,
	extra:   PipelineCauseExtra = {},
): Error {
	// The three answer-step causes arise only after the lookups ran, so each
	// has the lookups' results. One raised without them is a defect of the
	// caller, reported as such and not as a failure with nothing found.
	const answerStepFailed = (reason: AnswerStepFailureReason): Error => {
		if (extra.found === undefined) {
			throw new Error(`errorForPipelineCause: cause '${cause}' arises after the lookups ran and was raised without their results`);
		}
		return new ShaperAnswerStepFailedError(reason, message, extra.found);
	};
	switch (cause) {
		case 'invalid-input':
			return new ShaperInvalidInputError(message);
		case 'planner-prompt-missing':
			// Found before any lookup ran: nothing to carry.
			return new ShaperPromptMissingError(extra.promptPath ?? message);
		case 'answer-prompt-missing':
			// A fault of the installation, named as one, with what the lookups found.
			return new ShaperPromptMissingError(extra.promptPath ?? message, extra.found);
		case 'planner-model-failed':
			return new ShaperLlmUnavailableError(message, 'planning');
		case 'answer-model-failed':
			return answerStepFailed('model-failed');
		case 'answer-invalid':
			return answerStepFailed('invalid-answer');
		case 'bundle-invalid':
			return answerStepFailed('invalid-bundle');
		case 'empty-plan':
			return new ShaperNoPlanError(message);
		default: {
			const unreachable: never = cause;
			throw new Error(`errorForPipelineCause: unhandled cause ${String(unreachable)}`);
		}
	}
}

function settlePipelineOutcome(
	outcome: PipelineOutcome,
	stamp:   (raw: BundleLayers, explorationCount: number, report: AnswerReport) => AnalyzeContextBundle,
): { bundle: AnalyzeContextBundle; explorationCount: number } | null {
	if (outcome.kind === 'not-applicable') return null;
	if (outcome.kind === 'did-not-proceed') {
		throw errorForPipelineCause(outcome.cause, outcome.message, { promptPath: outcome.promptPath, found: outcome.found });
	}
	const bundle = stamp(outcome.raw, outcome.explorationCount, outcome.found.report);
	const v = validateBundleWithErrors(bundle);
	if (!v.ok) {
		throw errorForPipelineCause('bundle-invalid', v.errors.join('; '), { found: outcome.found });
	}
	return { bundle, explorationCount: outcome.explorationCount };
}

function legacyShaperPromptPathFor(
	shaperId: 'code' | 'docs' | 'data' | 'infra' | 'generic',
): string {
	return PROMPT_PATHS[shaperId];
}

function shaperFor(
	mode:    'classification' | 'run' | 'task',
	target?: RunTarget | TaskTarget,
): ClassificationShaper | RunShaper | TaskShaper {
	if (mode === 'classification') {
		const shaperId: ShaperId = 'classification';
		return {
			buildClassificationBundle: (
				input: ClassificationShapeInput,
				opts:  ShapeOpts,
			): Promise<AnalyzeContextBundle> =>
				runShaper({
					promptPath:     PROMPT_PATHS[shaperId],
					invocationMode: 'classification',
					shaperId,
					inputs:         input,
					opts,
				}),
		};
	}

	if (mode === 'run') {
		if (target === undefined) {
			throw new TypeError("shaperFor(mode='run', target): target is required");
		}
		const shaperId: ShaperId = shaperIdForRun(target as RunTarget);
		return {
			buildRunBundle: (
				input: RunShapeInput,
				opts:  ShapeOpts,
			): Promise<AnalyzeContextBundle> =>
				runShaper({
					promptPath:     PROMPT_PATHS[shaperId],
					invocationMode: 'run',
					shaperId,
					inputs:         input,
					opts,
				}),
		};
	}

	if (target === undefined) {
		throw new TypeError("shaperFor(mode='task', target): target is required");
	}
	if (target === 'generic') {
		throw new TypeError(
			"shaperFor(mode='task', target='generic'): task-level dispatch routes by " +
				'task family namespace; generic is invalid at task scope',
		);
	}
	const shaperId: ShaperId = shaperIdForTask(target as TaskTarget);
	return {
		buildTaskBundle: (
			input: TaskShapeInput,
			opts:  ShapeOpts,
		): Promise<AnalyzeContextBundle> =>
			runShaper({
				promptPath:     PROMPT_PATHS[shaperId],
				invocationMode: 'task',
				shaperId,
				inputs:         input,
				opts,
			}),
	};
}

class ScopeRefUnresolvedError extends Error {
	constructor(message: string) {
		super(message);
		this.name = 'ScopeRefUnresolvedError';
	}
}

class ScopeKindTargetMismatchError extends Error {
	constructor(kind: string, target: string, allowed: readonly string[]) {
		super(
			`scopeRef.kind='${kind}' is incompatible with target='${target}'. ` +
				`Allowed kinds for this target: ${allowed.join(', ')}.`,
		);
		this.name = 'ScopeKindTargetMismatchError';
	}
}

class ScopeNotIndexedError extends Error {
	readonly scopePath:    string;
	readonly registeredAs: string | undefined;

	constructor(scopePath: string, registeredAs: string | undefined, reason: string) {
		super(
			`Scope ${scopePath} produced an empty graph closure. ` +
				(registeredAs !== undefined
					? `Registered repo: ${registeredAs}. `
					: 'No registered repo contains this path. ') +
				`Reason: ${reason}. ` +
				`Run \`insrc repo add <path>\` and let the indexer finish ` +
				`(status: 'ready') before re-running analyze.`,
		);
		this.name = 'ScopeNotIndexedError';
		this.scopePath = scopePath;
		this.registeredAs = registeredAs;
	}
}

function scopeErrorMapping(err: unknown): ScopeErrorMapping | undefined {
	if (err instanceof ScopeNotIndexedError) {
		return { code: 'scope-not-indexed', message: err.message, data: { scopePath: err.scopePath, registeredAs: err.registeredAs } };
	}
	if (err instanceof ScopeRefUnresolvedError) return { code: 'scope-ref-unresolved', message: err.message };
	if (err instanceof ScopeKindTargetMismatchError) return { code: 'scope-ref-kind-target-mismatch', message: err.message };
	return undefined;
}

async function ensureNonEmptyClosure(
	scope: ResolvedScope,
	deps?: Pick<ScopeDeps, 'listRepos' | 'listEntitiesForRepo'>,
): Promise<string | undefined> {
	// Data-only scopes don't need a code graph.
	if (scope.kind === 'connection') {
		log.debug({ scope: scope.value }, 'ensureNonEmptyClosure: skipping connection-kind scope');
		return undefined;
	}

	const scopePath = freshnessPathOf(scope);
	if (scopePath.length === 0) {
		// Empty or non-filesystem scope; nothing we can check.
		return undefined;
	}

	// Find the longest-prefix registered repo containing the scope.
	let repos: readonly RegisteredRepo[];
	try {
		repos = deps !== undefined ? await deps.listRepos() : await listRepos(null);
	} catch (err) {
		// Registry unreachable (e.g. graph store not initialised in a
		// test harness). We do NOT throw ScopeNotIndexedError here --
		// the invariant cannot evaluate its precondition. The driver
		// proceeds; downstream tools that need graph data will either
		// fall back or fail with their own errors.
		log.debug(
			{ scope: scopePath, err: (err as Error).message },
			'ensureNonEmptyClosure: registry read failed; skipping invariant',
		);
		return undefined;
	}

	// Pristine registry: no repos registered at all. Most likely a
	// test harness or a first-time user who hasn't run `insrc repo
	// add` yet. We cannot meaningfully enforce the invariant in this
	// state (there's no expected closure to compare against), so we
	// skip silently and let the shaper fall back to filesystem tools.
	if (repos.length === 0) {
		log.debug(
			{ scope: scopePath },
			'ensureNonEmptyClosure: registry pristine; skipping invariant',
		);
		return undefined;
	}

	let best: RegisteredRepo | undefined;
	for (const r of repos) {
		const isPrefix = scopePath === r.path || scopePath.startsWith(`${r.path}/`);
		if (!isPrefix) continue;
		if (best === undefined || r.path.length > best.path.length) {
			best = r;
		}
	}

	if (best === undefined) {
		throw new ScopeNotIndexedError(
			scopePath,
			undefined,
			'no registered repo contains the scope path',
		);
	}

	// Count entities indexed for this repo. Stops at the first hit;
	// no need to materialise the full list.
	const entities = deps !== undefined
		? await deps.listEntitiesForRepo(best.path)
		: await listEntitiesForRepo(null, best.path);
	if (entities.length === 0) {
		throw new ScopeNotIndexedError(
			scopePath,
			best.path,
			`registered repo has zero indexed entities (status: ${best.status})`,
		);
	}

	log.debug(
		{ scope: scopePath, repo: best.path, entityCount: entities.length },
		'ensureNonEmptyClosure: closure non-empty',
	);
	return best.path;
}

async function assembleLiveProjectContext(
	db:   DbClient,
	repo: string,
	opts: AssembleLiveProjectContextOpts = {},
): Promise<LiveProjectContext> {
	const maxDecisions      = opts.maxDecisions      ?? DEFAULTS.maxDecisions;
	const maxConstraints    = opts.maxConstraints    ?? DEFAULTS.maxConstraints;
	const maxSubjects       = opts.maxSubjects       ?? DEFAULTS.maxSubjects;
	const maxRecentActivity = opts.maxRecentActivity ?? DEFAULTS.maxRecentActivity;

	const summaries = await listDocSummariesForRepo(db, repo);
	const entityIds = await listDocSummaryEntityIdsForRepo(db, repo);
	const totalDocs = summaries.length;

	// If we have summaries but the entity-id list is shorter (an entity
	// was deleted between the two calls), zip up to the shorter length.
	// This is a snapshot inconsistency, not a bug -- the next assemble
	// call will see the reconciled state.
	const pairs: Array<{ summary: DocSummary; entityId: string }> = [];
	const zipLen = Math.min(summaries.length, entityIds.length);
	for (let i = 0; i < zipLen; i++) {
		pairs.push({ summary: summaries[i]!, entityId: entityIds[i]! });
	}

	// Family breakdown -- initialise every family to 0 so callers can
	// iterate without missing-key checks.
	const familyBreakdown: Record<DocFamily, number> = {
		design: 0, plans: 0, docs: 0, adr: 0, rfc: 0, spec: 0,
		changelog: 0, readme: 0, other: 0,
	};
	for (const { summary } of pairs) {
		familyBreakdown[summary.family] += 1;
	}

	// Total code entities -- for the summary's "how much of the repo is
	// code vs docs" comparison. Cheap point count over the entity table
	// filtered by non-artefact.
	const allEntities = await listEntitiesForRepo(db, repo);
	const totalCodeEntities = allEntities.filter(e => e.artifact !== true).length;

	// Placeholder count -- summaries where the LLM call failed and
	// left an errorCode.
	const placeholderCount = pairs.filter(p => p.summary.errorCode !== undefined).length;

	// Decisions: gather all keyDecisions, cite source. Skip placeholder
	// rows (their empty arrays contribute nothing). Cap at maxDecisions.
	const decisions: CitedDecision[] = [];
	for (const { summary, entityId } of pairs) {
		if (summary.errorCode !== undefined) continue;
		for (const d of summary.keyDecisions) {
			if (decisions.length >= maxDecisions) break;
			decisions.push({
				decision:       d,
				sourceEntityId: entityId,
				family:         summary.family,
				docTitle:       summary.title,
			});
		}
		if (decisions.length >= maxDecisions) break;
	}

	// Constraints: same shape.
	const constraints: CitedConstraint[] = [];
	for (const { summary, entityId } of pairs) {
		if (summary.errorCode !== undefined) continue;
		for (const c of summary.keyConstraints) {
			if (constraints.length >= maxConstraints) break;
			constraints.push({
				constraint:     c,
				sourceEntityId: entityId,
				family:         summary.family,
				docTitle:       summary.title,
			});
		}
		if (constraints.length >= maxConstraints) break;
	}

	if (opts.report !== undefined) {
		// How many the summaries hold, counted past the limits.
		let foundDecisions = 0;
		let foundConstraints = 0;
		for (const { summary } of pairs) {
			if (summary.errorCode !== undefined) continue;
			foundDecisions   += summary.keyDecisions.length;
			foundConstraints += summary.keyConstraints.length;
		}
		const limitsReached: NonNullable<LiveProjectContextReport['limitsReached']> = [];
		if (foundDecisions > decisions.length)     limitsReached.push({ what: 'decisions',   limit: maxDecisions,   found: foundDecisions });
		if (foundConstraints > constraints.length) limitsReached.push({ what: 'constraints', limit: maxConstraints, found: foundConstraints });
		opts.report.limitsReached = limitsReached;
		opts.report.sourceEntityIds = [...new Set([...decisions, ...constraints].map(x => x.sourceEntityId))];
	}

	// Top subjects: tally, sort by count desc.
	const subjectCounts = new Map<string, number>();
	for (const { summary } of pairs) {
		if (summary.errorCode !== undefined) continue;
		for (const s of summary.subjects) {
			const key = s.toLowerCase();
			subjectCounts.set(key, (subjectCounts.get(key) ?? 0) + 1);
		}
	}
	const topSubjects: SubjectRollup[] = Array.from(subjectCounts.entries())
		.sort((a, b) => b[1] - a[1])
		.slice(0, maxSubjects)
		.map(([subject, docCount]) => ({ subject, docCount }));

	// Recent activity: sort by summarisedAt desc.
	const recentActivity: DocRecentActivity[] = pairs
		.filter(p => p.summary.errorCode === undefined)
		.map(({ summary, entityId }) => {
			// entity.file lookup would be an extra LMDB read per entity;
			// the summary title carries enough for the UI to render.
			// If the file path is critical, callers can hydrate via
			// getEntity(entityId).
			return {
				entityId,
				file:         '',      // populated below via a single sweep
				title:        summary.title,
				family:       summary.family,
				summarisedAt: summary.summarisedAt,
			};
		})
		.sort((a, b) => b.summarisedAt.localeCompare(a.summarisedAt))
		.slice(0, maxRecentActivity);

	// Populate file paths for the recent-activity entries. One LMDB
	// sweep to build entityId -> file map, then join. Bounded by
	// maxRecentActivity so the sweep cost is trivial.
	if (recentActivity.length > 0) {
		const fileByEntity = new Map<string, string>();
		for (const e of allEntities) {
			fileByEntity.set(e.id, e.file);
		}
		for (let i = 0; i < recentActivity.length; i++) {
			const cur = recentActivity[i]!;
			(recentActivity as DocRecentActivity[])[i] = {
				...cur,
				file: fileByEntity.get(cur.entityId) ?? '',
			};
		}
	}

	// Double-check totalDocs against the secondary-index count -- if
	// they disagree, prefer the index count (it's the authoritative
	// per-repo tally).
	const indexCount = await countDocSummariesForRepo(db, repo);

	return {
		repo,
		generatedAt: new Date().toISOString(),
		totalDocs:   Math.max(totalDocs, indexCount),
		totalCodeEntities,
		familyBreakdown,
		decisions,
		constraints,
		topSubjects,
		recentActivity,
		placeholderCount,
	};
}

function isModelCallFailure(err: unknown): boolean {
	if (err instanceof ModelCallFailedError) return true;
	if (!(err instanceof Error)) return false;
	const msg = withoutQuotedAnswer(err.message);
	// The provider's own wording for a failed call opens the message
	// (after the retry helper's prefix, when there is one). It is never
	// matched further in, where it could be quoted text.
	const own = msg.replace(RETRY_PREFIX, '');
	for (const text of CLI_FAILURE_TEXTS) {
		if (own.startsWith(text)) return true;
	}
	// The local provider wraps a connection failure with its own
	// prefix, and a socket error can be nested in another's message,
	// so these are matched anywhere -- outside a quoted answer.
	for (const text of OLLAMA_FAILURE_TEXTS) {
		if (msg.includes(text)) return true;
	}
	return false;
}

function modelCallFailureDetail(err: unknown): string {
	if (err instanceof ModelCallFailedError) return err.detail;
	return err instanceof Error ? err.message : String(err);
}

function createRepoIgnoreFilter(repoPath: string): RepoIgnoreFilter {
	const absRepo = resolve(repoPath);
	if (!existsSync(join(absRepo, '.git'))) {
		log.debug({ repo: absRepo }, 'not a git repo; using permissive filter');
		return permissiveFilter(absRepo);
	}

	let files: string[];
	try {
		// Same flags the indexer uses. --cached: tracked; --others: not
		// tracked but not ignored either (fresh files); --exclude-
		// standard: honour .gitignore + .git/info/exclude + global
		// gitignore. -z: NUL-separated to survive filenames with
		// newlines (rare but not impossible).
		const stdout = execFileSync(
			'git',
			['ls-files', '--cached', '--others', '--exclude-standard', '-z'],
			{ cwd: absRepo, maxBuffer: 50 * 1024 * 1024, encoding: 'utf8' },
		);
		files = stdout.split('\0').filter(Boolean);
	} catch (err) {
		log.warn(
			{ repo: absRepo, err: String(err) },
			'git ls-files failed; degrading to permissive filter',
		);
		return permissiveFilter(absRepo);
	}

	const trackedFiles = new Set<string>();
	const trackedDirs = new Set<string>();
	trackedDirs.add(absRepo);
	for (const relFile of files) {
		const abs = resolve(absRepo, relFile);
		trackedFiles.add(abs);
		// Add every ancestor dir up to (but not past) the repo root
		// so a query for "is this DIRECTORY included?" answers true
		// when the dir has at least one tracked descendant.
		let dir = dirname(abs);
		while (dir.length >= absRepo.length && dir !== absRepo) {
			if (trackedDirs.has(dir)) break;
			trackedDirs.add(dir);
			const parent = dirname(dir);
			if (parent === dir) break;
			dir = parent;
		}
	}

	log.debug(
		{ repo: absRepo, files: trackedFiles.size, dirs: trackedDirs.size },
		'repo ignore filter ready',
	);

	return {
		repoPath:  absRepo,
		gitBacked: true,
		isIncluded(absPath: string): boolean {
			const abs = resolve(absPath);
			return trackedFiles.has(abs) || trackedDirs.has(abs);
		},
		include<T extends { readonly path: string }>(items: readonly T[]): T[] {
			return items.filter(i => trackedFiles.has(resolve(i.path)) || trackedDirs.has(resolve(i.path)));
		},
	};
}

function permissiveIgnoreFilter(repoPath = ''): RepoIgnoreFilter {
	return permissiveFilter(repoPath);
}

function resolveRole(
	role:      RoleId,
	cfg:       AnalyzeConfig,
	repoPath:  string | undefined,
	deps:      RoleRouterDeps = {},
): RoleResolution {
	return resolveRoleInternal(role, cfg, repoPath, deps).resolution;
}

function createRoleRouter(deps: RoleRouterDeps = {}): RoleRouter {
	const cache = new Map<string, ResolvedProvider>();
	return {
		resolveProviderForRole(role, cfg, repoPath) {
			const key = `${role} ${repoPath ?? ''}`;
			const hit = cache.get(key);
			if (hit !== undefined) return hit;
			const built = materialize(resolveRoleInternal(role, cfg, repoPath, deps), cfg, deps);
			cache.set(key, built);
			return built;
		},
		resolveSummariser(cfg) {
			// Delegate to the summariser factory so the summariser-stays-local
			// decoupling is wrapped, not re-implemented; stamp a resolution so
			// summariser access is attributed like every other role.
			const provider = buildSummariserProvider(cfg);
			const resolution: RoleResolution = {
				role:           SUMMARISER_ROLE,
				tier:           'cheap',
				runner:         cfg.summariserProvider,
				model:          cfg.summariserModel,
				clampedByFloor: false,
			};
			return { provider, resolution };
		},
	};
}

function modelFacingBundleSchema(opts: { readonly withMeta: boolean }): Record<string, unknown> {
	const key = opts.withMeta ? 'withMeta' : 'layersOnly';
	const kept = modelFacing[key];
	if (kept !== undefined) return kept;

	const cloned = JSON.parse(JSON.stringify(ANALYZE_CONTEXT_BUNDLE_SCHEMA)) as Record<string, unknown>;
	const props = cloned['properties'] as Record<string, unknown>;
	delete props['report'];
	delete cloned['definitions'];   // used by `report` only
	if (!opts.withMeta) {
		delete props['meta'];
		cloned['required'] = (cloned['required'] as string[]).filter(k => k !== 'meta');
	}
	// Its own identity: not the stored schema's `$id`.
	delete cloned['$id'];
	modelFacing[key] = cloned;
	return cloned;
}

